public class Main {
    static int maxSumTwoNoOverlap(int[] nums, int L, int M) {
        int n = nums.length;
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

        int best = 0;
        for (int i = 0; i <= n - L; i++) {              // every start of the L window
            for (int j = 0; j <= n - M; j++) {           // every start of the M window
                if (i + L <= j || j + M <= i) {           // only accept non-overlapping pairs
                    int total = (prefix[i + L] - prefix[i]) + (prefix[j + M] - prefix[j]);
                    best = Math.max(best, total);
                }
            }
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println(maxSumTwoNoOverlap(new int[]{0, 6, 5, 2, 2, 5, 1, 9, 4}, 1, 2));
    }
}

