#include <bits/stdc++.h>
using namespace std;

int maxSumTwoNoOverlap(vector<int>& nums, int L, int M) {
    int n = nums.size();
    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

    long long best = 0;
    for (int i = 0; i <= n - L; i++) {                  // every start of the L window
        for (int j = 0; j <= n - M; j++) {               // every start of the M window
            if (i + L <= j || j + M <= i) {               // only accept non-overlapping pairs
                long long total = (prefix[i + L] - prefix[i]) + (prefix[j + M] - prefix[j]);
                best = max(best, total);
            }
        }
    }
    return (int)best;
}

int main() {
    vector<int> nums = {0, 6, 5, 2, 2, 5, 1, 9, 4};
    cout << maxSumTwoNoOverlap(nums, 1, 2) << endl;
    return 0;
}

