    static int bestOrder(int[] prefix, int n, int first, int second) {
        int ans = 0, maxFirst = 0;
        for (int i = first + second; i <= n; i++) {
            maxFirst = Math.max(maxFirst, prefix[i - second] - prefix[i - second - first]);
            ans = Math.max(ans, maxFirst + prefix[i] - prefix[i - second]);
        }
        return ans;
    }

    static int maxSumTwoNoOverlap(int[] nums, int L, int M) {
        int n = nums.length;
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];
        return Math.max(bestOrder(prefix, n, L, M), bestOrder(prefix, n, M, L));  // both orderings
    }

    public static void main(String[] args) {
        System.out.println(maxSumTwoNoOverlap(new int[]{0, 6, 5, 2, 2, 5, 1, 9, 4}, 1, 2));
    }
}

